import { prisma } from '../config/prisma.js';

/**
 * 🆔 IDENTITY GENERATORS
 *
 * Player IDs ("APX-0001") and match numbers (1, 2, 3 …) are generated by the
 * backend so the admin never types them. Both are unique per tenant.
 */

const MAP_LABEL: Record<string, string> = {
  BERMUDA: 'Bermuda',
  PURGATORY: 'Purgatory',
  KALAHARI: 'Kalahari',
  ALPINE: 'Alpine',
  NEXTERRA: 'Nexterra',
};

const MATCH_TYPE_LABEL: Record<string, string> = {
  SOLO: 'Solo',
  DUO: 'Duo',
  SQUAD: 'Squad',
};

/** First 3 alphanumerics of the tenant subdomain, e.g. "apex-ff" -> "APE". */
export function playerCodePrefix(subdomain: string | null | undefined, brandName?: string | null): string {
  const cleaned = (subdomain || brandName || 'PLY').replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
  return (cleaned.slice(0, 3) || 'PLY').padEnd(3, 'X');
}

/**
 * Next readable player code for the tenant, e.g. "APX-0007".
 * Sequential per prefix; concurrency is covered by the unique constraint plus
 * a pre-check retry in the registration paths.
 */
export async function nextPlayerCode(tenantId: string): Promise<string> {
  const tenant = await prisma.tenant.findUnique({
    where: { id: tenantId },
    select: { subdomain: true, brandName: true },
  });
  const prefix = playerCodePrefix(tenant?.subdomain, tenant?.brandName);
  const rows = await prisma.user.findMany({
    where: { tenantId, playerCode: { startsWith: `${prefix}-` } },
    select: { playerCode: true },
  });
  let max = 0;
  for (const row of rows) {
    const suffix = row.playerCode?.split('-')[1];
    const value = Number(suffix);
    if (Number.isFinite(value) && value > max) max = value;
  }
  return `${prefix}-${String(max + 1).padStart(4, '0')}`;
}

/** Unique player code with a few retries in case of a rare race. */
export async function allocatePlayerCode(tenantId: string): Promise<string> {
  for (let attempt = 0; attempt < 10; attempt++) {
    const code = await nextPlayerCode(tenantId);
    const clash = await prisma.user.findFirst({
      where: { tenantId, playerCode: code },
      select: { id: true },
    });
    if (!clash) return code;
  }
  // Extremely unlikely fallback: time-based suffix keeps it unique enough.
  return `PLY-${Date.now().toString().slice(-4)}`;
}

/** Next auto match number for the tenant: 1, 2, 3 … */
export async function nextMatchNumber(tenantId: string): Promise<number> {
  const agg = await prisma.tournament.aggregate({
    where: { tenantId },
    _max: { matchNumber: true },
  });
  return (agg._max.matchNumber ?? 0) + 1;
}

/** "50 | Bermuda Solo" — auto title when the admin does not type one. */
export function autoMatchTitle(mapType: string, matchType: string, matchNumber: number): string {
  const map = MAP_LABEL[mapType] ?? mapType;
  const type = MATCH_TYPE_LABEL[matchType] ?? matchType;
  return `${matchNumber} | ${map} ${type}`;
}
